"""Independent invariant checker for successful outputs."""
import json

LABELS = None
EDGES = None

def all_paths(doc):
    n = doc["n"]
    edges = doc["edges"]
    outs = {i: [] for i in range(n)}
    for i, e in enumerate(edges):
        outs[e["u"]].append(i)
    res = []
    stack = [(0, [])]
    while stack:
        node, path = stack.pop()
        if node == n - 1:
            if path:
                res.append(tuple(path))
            continue
        for oe in outs[node]:
            try:
                v = edges[oe]["v"]
            except IndexError:
                raise AssertionError("bad path")
            stack.append((v, path + [oe]))
    # dedupe (should not be needed but enumerations must be unique)
    assert len(set(res)) == len(res)
    return res

def check(doc, out):
    errs = []
    def E(m): errs.append(m)

    n = doc["n"]; edges = doc["edges"]; rounds = doc["rounds"]
    ne = len(edges)
    if set(out) != {"rounds", "metrics", "classes", "summary"}:
        E("top-level keys")
        return errs

    mkeys = {"host_probe_tx","network_ping_tx","network_ack_tx","host_ack_tx",
             "deduplicated_ping","capacity_drops","late_ping","ignored_ack",
             "allocations","cache_peak","peak_entries","end_us"}
    if set(out["metrics"]) != mkeys:
        E("metrics keys")
    else:
        mm = out["metrics"]
        for k in mkeys - {"cache_peak"}:
            t = type(mm[k])
            if t is not int:
                E(f"metric {k} not int: {mm[k]!r} {t}")
        if mm["host_probe_tx"] != len(rounds):
            E("host_probe_tx != #rounds")
        if type(mm["cache_peak"]) is not list or len(mm["cache_peak"]) != n:
            E("cache_peak shape")
        else:
            for x in mm["cache_peak"]:
                if type(x) is not int:
                    E("cache_peak entry type")
        if len(out["rounds"]) != len(rounds):
            E("rounds length")
        for c in mm["cache_peak"]:
            pass
        if type(mm["peak_entries"]) is not int or mm["peak_entries"] > sum(mm.get("cache_peak", [])):
            E("peak_entries vs per-node peaks")
        if mm["end_us"] < 0:
            E("end_us negative")
        dl = max((r["launch_us"] + r["timeout_us"] + 1 for r in rounds), default=0)
        if rounds and mm["end_us"] < dl:
            E(f"end_us {mm['end_us']} < max release {dl}")

    # rounds section
    for i, r in enumerate(out["rounds"]):
        if set(r) != {"id","started","source_final_us","source_complete","host_delivery_us","source_proof"}:
            E(f"round {i} keys")
            continue
        if r["id"] != i:
            E("round id")
        if type(r["started"]) is not bool:
            E(f"round {i} started not bool")
        launched = rounds[i]["launch_us"]; deadline = launched + rounds[i]["timeout_us"]
        if r["started"]:
            if r["source_final_us"] is None or type(r["source_final_us"]) is not int:
                E(f"round {i} final_us null when started")
            elif r["source_final_us"] > deadline:
                E(f"round {i} finalizes after deadline")
            if r["source_complete"] is None or type(r["source_complete"]) is not bool:
                E(f"round {i} source_complete null when started")
            sp = r["source_proof"]
            if type(sp) is not list or any(type(x) is not int for x in sp):
                E(f"round {i} proof types")
            elif sp != sorted(set(sp)):
                E(f"round {i} proof not sorted/distinct")
            for e in sp:
                if not 0 <= e < ne:
                    E(f"round {i} proof edge out of range")
        else:
            if (r["source_final_us"], r["source_complete"], r["host_delivery_us"]) is not (None, None, None):
                E(f"round {i} not-started fields")
            if r["source_proof"] != []:
                E(f"round {i} not-started proof not []
")
        if r["host_delivery_us"] is not None:
            if type(r["host_delivery_us"]) is not int:
                E(f"round {i} host_delivery type")
            if rounds[i]["drop_host_ack"]:
                E(f"round {i} host delivery despite drop_host_ack")
            if r["source_final_us"] is None:
                E(f"round {i} host delivery with no finalization")
            elif r["host_delivery_us"] != r["source_final_us"] + rounds[i]["host_delay_us"]:
                E(f"round {i} host delivery time")
        if r["started"] and not r["source_complete"] and out["metrics"]["host_ack_tx"] < 1:
            E("host_ack_tx")
    if out["metrics"]["host_ack_tx"] > len(rounds):
        E("host_ack_tx > rounds")

    # classes section
    paths = all_paths(doc)
    classes = out["classes"]
    if classes != sorted(classes, key=lambda c: c["signature"]):
        E("classes not sorted")
    # sort key must match ASCII label tuple comparison
    for i in range(len(classes) - 1):
        a, b = classes[i]["signature"], classes[i+1]["signature"]
        if a == b:
            E("duplicate class signatures")
    # check the complete signature multiset
    got_sigs = {}
    for c in classes:
        got_sigs[tuple(c["signature"])] = c
    want_sigs = {}
    for p in paths:
        sig = tuple(edges[e]["label"] for e in p)
        want_sigs.setdefault(sig, []).append(p)
    if set(got_sigs) != set(want_sigs):
        E("signature set mismatch")
    for sig, plist in want_sigs.items():
        c = got_sigs.get(tuple(sig))
        if c is None:
            continue
        if set(c) != {"signature","candidate_count","evidence_rounds","state","candidate_witnesses"}:
            E("class keys")
            continue
        if c["candidate_count"] != len(plist):
            E(f"candidate_count {c['candidate_count']} != {len(plist)}")
        if c["state"] not in {"unobserved","unique","ambiguous"}:
            E("state value")
        if c["state"] == "unobserved" and c["evidence_rounds"]:
            E("state/evidence mismatch")
        if c["state"] == "unique" and c["candidate_count"] != 1:
            E("unique state with count != 1")
        if c["state"] == "ambiguous" and c["candidate_count"] < 2:
            E("ambiguous state with count < 2")
        if c["evidence_rounds"] != sorted(set(c["evidence_rounds"])):
            E("evidence_rounds not sorted/distinct")
        for rid in c["evidence_rounds"]:
            if rid not in range(len(rounds)):
                E("evidence round id out of range")
                continue
            r = out["rounds"][rid]
            if r["host_delivery_us"] is None:
                E(f"evidence round {rid} without host delivery")
            proof = set(r["source_proof"])
            if not any(all(e in proof for e in p) for p in plist):
                E(f"class {sig} evidence round {rid} not justified by proof")
        if len(plist) == 1:
            if c["candidate_witnesses"] != [list(plist[0])]:
                E(f"witness for singleton class: {c['candidate_witnesses']} vs {plist}")
        else:
            wcount = len(c["candidate_witnesses"])
            if wcount != 2:
                E(f"witness count {wcount} for multi-candidate class")
            else:
                as_set = {tuple(w) for w in c["candidate_witnesses"]}
                if len(as_set) != 2 or not all(tuple(w) in set(plist) for w in c["candidate_witnesses"]):
                    E("witnesses must be 2 distinct concrete paths of the class")
        # any witness must be a contiguous s-d path
        for w in c["candidate_witnesses"]:
            node = 0
            for eid in w:
                if edges[eid]["u"] != node:
                    E("witness not contiguous")
                    break
                node = edges[eid]["v"]
            if node != n - 1:
                E("witness does not reach destination")

    # summary
    s = out["summary"]
    if set(s) != {"topology_paths","observable_classes","observed_classes",
                  "unique_observed_classes","ambiguous_observed_classes",
                  "path_evidence_lower","path_evidence_upper","coverage_status"}:
        E("summary keys")
        return errs
    obs = [c for c in classes if c["evidence_rounds"]]
    if s["topology_paths"] != len(paths): E("topology_paths")
    if s["observable_classes"] != len(classes): E("observable_classes")
    if s["observed_classes"] != len(obs): E("observed_classes")
    if s["unique_observed_classes"] != sum(1 for c in obs if c["candidate_count"] == 1): E("unique_observed")
    if s["ambiguous_observed_classes"] != sum(1 for c in obs if c["candidate_count"] != 1): E("ambiguous_observed")
    if s["path_evidence_lower"] != len(obs): E("lower")
    if s["path_evidence_upper"] != sum(c["candidate_count"] for c in obs): E("upper")
    want_cov = ("no-routes" if len(classes)==0 else "no-evidence" if not obs else
                "complete" if len(obs)==len(classes) else "partial")
    if s["coverage_status"] != want_cov: E("coverage_status")
    return errs
PYEOF
